import{_ as s,o as n,c as a,a0 as t}from"./chunks/framework.BE1i3JtZ.js";const g=JSON.parse('{"title":"H5 端 Docker 部署设计文档（重构版：宿主机构建 + Nginx 轻量容器）","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-09-16-h5-docker-deploy-design.md","filePath":"superpowers/specs/2026-09-16-h5-docker-deploy-design.md"}'),l={name:"superpowers/specs/2026-09-16-h5-docker-deploy-design.md"};function i(o,e,d,p,c,r){return n(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="h5-端-docker-部署设计文档-重构版-宿主机构建-nginx-轻量容器" tabindex="-1">H5 端 Docker 部署设计文档（重构版：宿主机构建 + Nginx 轻量容器） <a class="header-anchor" href="#h5-端-docker-部署设计文档-重构版-宿主机构建-nginx-轻量容器" aria-label="Permalink to &quot;H5 端 Docker 部署设计文档（重构版：宿主机构建 + Nginx 轻量容器）&quot;">​</a></h1><ul><li>日期：2026-09-16</li><li>状态：已批准</li><li>架构分类：部署基建（不涉及 <code>.uvue</code> / <code>.uts</code>，不触碰 <code>unibestX-skill</code> 分册约束）</li></ul><hr><h2 id="_1-背景与重构动因" tabindex="-1">1. 背景与重构动因 <a class="header-anchor" href="#_1-背景与重构动因" aria-label="Permalink to &quot;1. 背景与重构动因&quot;">​</a></h2><h3 id="_1-1-历史方案回顾与废弃原因" tabindex="-1">1.1 历史方案回顾与废弃原因 <a class="header-anchor" href="#_1-1-历史方案回顾与废弃原因" aria-label="Permalink to &quot;1.1 历史方案回顾与废弃原因&quot;">​</a></h3><p>原方案试图在 Docker 容器内通过 <code>ubuntu:20.04</code> 下载并安装 HBuilderX Linux 官方桌面完整包（1.76GB 压缩包，解压后 3.7GB），并在容器内执行 <code>cli publish --platform h5</code>。</p><p>经过探针验证与实测，确认该方案存在以下严重工程硬伤，予以推翻重构：</p><ol><li><strong>软件属性与容器哲学违背</strong>：HBuilderX 为 Qt5 桌面 GUI 应用，官方未提供无头（headless）编译器。容器内必须后台运行 GUI 守护进程，其 <code>cli open</code> 进程会继承 stdout 占满 BuildKit 日志管道导致构建卡死，且 CLI 错误退出码恒为 0，错误捕获极脆弱。</li><li><strong>架构模拟性能极差</strong>：DCloud 官方仅提供 x86_64 包，无 ARM64 版本。在 Apple Silicon (Mac M 系列) 开发机上必须通过 Rosetta 2 模拟，光探针启动即耗时 8 分 28 秒；若包含 npm 依赖安装与项目编译，单次构建预计高达 15~30 分钟，极不实用。</li><li><strong>外部网络单点故障</strong>：构建阶段强依赖从 DCloud 官网实时拉取 1.76GB 大包，官方版本迭代或网络限速会导致构建直接失败。</li></ol><h3 id="_1-2-现代化前端部署标准" tabindex="-1">1.2 现代化前端部署标准 <a class="header-anchor" href="#_1-2-现代化前端部署标准" aria-label="Permalink to &quot;1.2 现代化前端部署标准&quot;">​</a></h3><p>行业标准前端 SPA / H5 容器化实践：</p><blockquote><p><strong>「编译归编译，运行归运行」</strong>：在具备完整编译环境（Node.js + 本地 HBuilderX CLI）的宿主机或 CI 节点执行构建，Docker 镜像仅作为轻量运行时（<code>nginx:alpine</code>），仅包含静态产物与 Nginx 配置。</p></blockquote><hr><h2 id="_2-目标与范围" tabindex="-1">2. 目标与范围 <a class="header-anchor" href="#_2-目标与范围" aria-label="Permalink to &quot;2. 目标与范围&quot;">​</a></h2><h3 id="_2-1-核心目标" tabindex="-1">2.1 核心目标 <a class="header-anchor" href="#_2-1-核心目标" aria-label="Permalink to &quot;2.1 核心目标&quot;">​</a></h3><ol><li><strong>轻量与秒级打包</strong>：Docker 镜像仅基于 <code>nginx:alpine</code>，构建时间由原来的 15~30 分钟降低至 <strong>1~2 秒</strong>，镜像体积由数 GB 降低至 <strong>约 25MB</strong>。</li><li><strong>多架构零损耗（Multi-Arch）</strong>：原生支持 <code>linux/amd64</code> 与 <code>linux/arm64</code>，Mac 本地无指令集转译损耗，生产 Linux 服务器原生高效运行。</li><li><strong>环境隔离与动态反代</strong>： <ul><li>区分测试服 (<code>test</code>) 与生产 (<code>prod</code>) 静态构建产物；</li><li>Nginx 使用官方 <code>templates</code> + <code>envsubst</code> 机制，在容器启动时动态注入后端 API 反代上游地址 <code>\${API_UPSTREAM}</code>。</li></ul></li><li><strong>统一开发与运维体验 (DX)</strong>： <ul><li>一份 <code>docker-compose.yml</code> 编排 <code>h5-test</code> 与 <code>h5-prod</code>；</li><li><code>package.json</code> 整合一键式命令，串联环境切换、前端打包与镜像构建。</li></ul></li></ol><h3 id="_2-2-明确非目标-yagni" tabindex="-1">2.2 明确非目标（YAGNI） <a class="header-anchor" href="#_2-2-明确非目标-yagni" aria-label="Permalink to &quot;2.2 明确非目标（YAGNI）&quot;">​</a></h3><ul><li>不在容器内执行 HBuilderX 安装与编译；</li><li>容器内不处理 HTTPS 证书（由外层网关/阿里云 SLB/CDN 统一负责 TLS 终止，容器仅监听 80 端口）；</li><li>不侵入修改现有核心业务与页面代码。</li></ul><hr><h2 id="_3-架构与数据流设计" tabindex="-1">3. 架构与数据流设计 <a class="header-anchor" href="#_3-架构与数据流设计" aria-label="Permalink to &quot;3. 架构与数据流设计&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[阶段 1: 宿主机 / CI 构建]</span></span>
<span class="line"><span>  pnpm build:test / pnpm build:prod</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ├─ switch-env.mjs 切换环境变量 (.env.production.local)</span></span>
<span class="line"><span>      └─ build-h5.mjs 触发本地 HBuilderX CLI 原生秒级编译</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼ 产物落盘</span></span>
<span class="line"><span>  unpackage/dist/build/web/ (index.html, assets/, static/)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[阶段 2: Docker 打包 (约 1-2 秒)]</span></span>
<span class="line"><span>  docker build -t unibestx-h5:prod .</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ├─ 基于 nginx:alpine (~25MB)</span></span>
<span class="line"><span>      ├─ 检查产物防空校验 (test -f unpackage/dist/build/web/index.html)</span></span>
<span class="line"><span>      ├─ COPY unpackage/dist/build/web/ -&gt; /usr/share/nginx/html</span></span>
<span class="line"><span>      └─ COPY deploy/nginx.conf -&gt; /etc/nginx/templates/default.conf.template</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[阶段 3: 容器运行时编排]</span></span>
<span class="line"><span>  docker compose up -d</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ├─ Nginx 官方 entrypoint 自动 envsubst 替换 \${API_UPSTREAM}</span></span>
<span class="line"><span>      ├─ 静态资源 30 天缓存与 Gzip 压缩</span></span>
<span class="line"><span>      ├─ Hash 路由 try_files 兜底</span></span>
<span class="line"><span>      └─ /api 请求透明代理至对应后端服务</span></span></code></pre></div><hr><h2 id="_4-文件与目录结构" tabindex="-1">4. 文件与目录结构 <a class="header-anchor" href="#_4-文件与目录结构" aria-label="Permalink to &quot;4. 文件与目录结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">文件路径</th><th style="text-align:left;">变更类型</th><th style="text-align:left;">职责描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Dockerfile</code></td><td style="text-align:left;"><strong>新增</strong></td><td style="text-align:left;">基于 <code>nginx:alpine</code> 的极简运行时镜像，拷贝静态产物和配置模板</td></tr><tr><td style="text-align:left;"><code>.dockerignore</code></td><td style="text-align:left;"><strong>新增</strong></td><td style="text-align:left;">构建上下文排除机制，白名单仅保留构建产物和 deploy 配置</td></tr><tr><td style="text-align:left;"><code>deploy/nginx.conf</code></td><td style="text-align:left;"><strong>新增</strong></td><td style="text-align:left;">支持 <code>envsubst</code> 的 Nginx 生产级配置模板（含 gzip、缓存、路由重定向、反向代理）</td></tr><tr><td style="text-align:left;"><code>docker-compose.yml</code></td><td style="text-align:left;"><strong>新增</strong></td><td style="text-align:left;">容器编排文件，支持 <code>h5-test</code> 与 <code>h5-prod</code> 两个服务</td></tr><tr><td style="text-align:left;"><code>deploy/.env.test</code></td><td style="text-align:left;"><strong>新增</strong></td><td style="text-align:left;">测试环境 compose 配置（端口映射如 8081、测试 API 代理地址）</td></tr><tr><td style="text-align:left;"><code>deploy/.env.prod</code></td><td style="text-align:left;"><strong>新增</strong></td><td style="text-align:left;">生产环境 compose 配置（端口映射如 8080、生产 API 代理地址）</td></tr><tr><td style="text-align:left;"><code>package.json</code></td><td style="text-align:left;"><strong>修改</strong></td><td style="text-align:left;">注入快捷命令：<code>docker:build:test</code>, <code>docker:build:prod</code>, <code>docker:up:test</code>, <code>docker:up:prod</code></td></tr><tr><td style="text-align:left;"><code>docs/guide/docker-deploy.md</code></td><td style="text-align:left;"><strong>新增</strong></td><td style="text-align:left;">完备的 Docker 部署操作手册（本地调试、生产部署、反向代理配置）</td></tr><tr><td style="text-align:left;"><code>deploy/probe/</code></td><td style="text-align:left;"><strong>清理</strong></td><td style="text-align:left;">废弃旧版 HBuilderX 容器探针目录，保持仓库整洁</td></tr></tbody></table><hr><h2 id="_5-详细技术规范" tabindex="-1">5. 详细技术规范 <a class="header-anchor" href="#_5-详细技术规范" aria-label="Permalink to &quot;5. 详细技术规范&quot;">​</a></h2><h3 id="_5-1-dockerfile-设计" tabindex="-1">5.1 Dockerfile 设计 <a class="header-anchor" href="#_5-1-dockerfile-设计" aria-label="Permalink to &quot;5.1 Dockerfile 设计&quot;">​</a></h3><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> nginx:alpine</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 注入 nginx 配置模板，nginx 官方镜像启动时会自动用环境变量替换并生成 default.conf</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> deploy/nginx.conf /etc/nginx/templates/default.conf.template</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 拷贝静态文件</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> unpackage/dist/build/web /usr/share/nginx/html</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EXPOSE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 80</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nginx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-g&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;daemon off;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h3 id="_5-2-dockerignore-设计" tabindex="-1">5.2 <code>.dockerignore</code> 设计 <a class="header-anchor" href="#_5-2-dockerignore-设计" aria-label="Permalink to &quot;5.2 \`.dockerignore\` 设计&quot;">​</a></h3><div class="language-gitignore vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gitignore</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*</span></span>
<span class="line"><span>!deploy/</span></span>
<span class="line"><span>!deploy/nginx.conf</span></span>
<span class="line"><span>!unpackage/dist/build/web/</span></span>
<span class="line"><span>!unpackage/dist/build/web/**</span></span></code></pre></div><p>仅将打包产物和 nginx 模板送入 Docker 构建上下文，使得 <code>transferring context</code> 小于 1MB，瞬间完成。</p><h3 id="_5-3-nginx-配置规范-deploy-nginx-conf" tabindex="-1">5.3 Nginx 配置规范 (<code>deploy/nginx.conf</code>) <a class="header-anchor" href="#_5-3-nginx-配置规范-deploy-nginx-conf" aria-label="Permalink to &quot;5.3 Nginx 配置规范 (\`deploy/nginx.conf\`)&quot;">​</a></h3><ul><li><strong>Gzip 压缩</strong>：开启常用文本与 JS/CSS 压缩；</li><li><strong>Hash 路由容错</strong>：<code>try_files $uri $uri/ /index.html;</code>；</li><li><strong>静态资源缓存</strong>：<code>/assets/</code> 设置 30 天缓存与 immutable；</li><li><strong>动态反向代理</strong>：配置 <code>location /api/ { proxy_pass \${API_UPSTREAM}; ... }</code>。</li></ul><hr><h2 id="_6-验证方案" tabindex="-1">6. 验证方案 <a class="header-anchor" href="#_6-验证方案" aria-label="Permalink to &quot;6. 验证方案&quot;">​</a></h2><ol><li><strong>前置构建验证</strong>：运行 <code>pnpm build:prod</code>，确认本地生成 <code>unpackage/dist/build/web/index.html</code>。</li><li><strong>镜像打包验证</strong>：运行 <code>docker build -t unibestx-h5:prod .</code>，耗时在 3 秒以内，镜像大小 &lt; 40MB。</li><li><strong>容器运行验证</strong>：启动容器，使用 curl 验证： <ul><li>根路径 <code>GET /</code> 返回 200 及 HTML；</li><li>静态资源 <code>GET /assets/...</code> 返回对应缓存响应头；</li><li>API 代理路径转发预期。</li></ul></li></ol>`,35)])])}const u=s(l,[["render",i]]);export{g as __pageData,u as default};
